INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO-106','beginner','Sprzęt i podzespoły / Hardware','Profile pamięci XMP i EXPO','','description: Wyższe ustawienia pamięci mogą powodować niestabilność. step: Zanotuj aktualny profil i porównaj go ze specyfikacją sprzętu.','','',''),
('beginner:ZERO-107','beginner','Serwis i diagnostyka / Service & Diagnostics','Rozmiar i format płyty głównej','','description: Płyta i obudowa muszą mieć zgodny rozmiar oraz mocowania. step: Przed zakupem porównaj format płyty, obudowy i rozmieszczenie portów.','','',''),
('beginner:ZERO-108','beginner','Sprzęt i podzespoły / Hardware','Gniazdo procesora','','description: Różne generacje procesorów mogą wymagać innych płyt lub wersji firmware. step: Sprawdź listę zgodności producenta przed zakupem części.','','',''),
('beginner:ZERO-109','beginner','Zasilanie / Power','Moc zasilacza a zapotrzebowanie','','description: Wartość w watach nie opisuje całej jakości ani zgodności zasilacza. step: Porównaj wymagania podzespołów oraz złącza z dokumentacją producentów.','','',''),
('beginner:ZERO-110','beginner','Obraz i ekran / Display','Złącza zasilania GPU','','description: Karta graficzna może wymagać określonych przewodów i wtyków. step: Sprawdź instrukcję karty i zasilacza; nie używaj przypadkowych przewodów modułowych.','','',''),
('beginner:ZERO-111','beginner','Serwis i diagnostyka / Service & Diagnostics','Wolne miejsce wokół komputera','','description: Zasłonięte wloty i wyloty powietrza pogarszają chłodzenie. step: Ustaw urządzenie na twardej powierzchni z drożnymi otworami.','','',''),
('beginner:ZERO-112','beginner','Serwis i diagnostyka / Service & Diagnostics','Laptop wyłącza się na baterii','','description: Nagłe wyłączenie może wynikać z baterii, temperatury lub systemu. step: Zanotuj poziom naładowania i sprawdź raport baterii.','','',''),
('beginner:ZERO-113','beginner','Zasilanie / Power','Zasilacz jest gorący','','description: Ciepło podczas pracy bywa normalne, lecz zapach spalenizny lub uszkodzona obudowa nie. step: Przerwij używanie podejrzanego zasilacza i skonsultuj go z serwisem.','','',''),
('beginner:ZERO-114','beginner','BIOS i rozruch / BIOS & Boot','Komputer uruchamia się sam','','description: Przyczyną mogą być ustawienia wybudzania, aktualizacje albo urządzenia zewnętrzne. step: Zanotuj godzinę zdarzenia i sprawdź ustawienia wybudzania.','','',''),
('beginner:ZERO-115','beginner','System i sterowniki / System & Drivers','Uśpienie i hibernacja','','description: Problemy po wznowieniu mogą zależeć od sterownika i zarządzania energią. step: Porównaj zachowanie po pełnym uruchomieniu oraz po uśpieniu.','','',''),
('beginner:ZERO-116','beginner','Zasilanie / Power','Bateria szybko traci energię','','description: Duże obciążenie i jasny ekran wpływają na czas pracy. step: Sprawdź aplikacje zużywające energię i raport stanu baterii.','','',''),
('beginner:ZERO-117','beginner','Zasilanie / Power','Ładowarka nie jest rozpoznawana','','description: Niektóre laptopy weryfikują zgodność zasilacza i kabla. step: Sprawdź oznaczenia oraz komunikat systemowy; nie używaj uszkodzonego przewodu.','','',''),
('beginner:ZERO-118','beginner','Peryferia / Peripherals','Port USB nie działa','','description: Przyczyną bywa urządzenie, kabel, port lub sterownik. step: Porównaj sprawne urządzenie na innym porcie bez używania nadmiernej siły.','','',''),
('beginner:ZERO-119','beginner','Zasilanie / Power','Przewód danych a przewód tylko do ładowania','','description: Podobnie wyglądające przewody mogą oferować różne funkcje. step: Sprawdź opis kabla i porównaj przewód z potwierdzoną transmisją danych.','','',''),
('beginner:ZERO-120','beginner','Dyski i dane / Storage & Data','Dysk zewnętrzny rozłącza się','','description: Przerwy mogą wynikać z przewodu, portu lub problemu nośnika. step: Wykonaj kopię dostępnych danych i porównaj sprawny kabel.','','',''),
('beginner:ZERO-121','beginner','Peryferia / Peripherals','Czytnik kart pamięci','','description: Brak odczytu karty nie zawsze oznacza jej uszkodzenie. step: Sprawdź zgodność formatu i drugi czytnik; nie formatuj karty z ważnymi danymi.','','',''),
('beginner:ZERO-122','beginner','Peryferia / Peripherals','Mysz działa z opóźnieniem','','description: Zakłócenia, bateria i obciążenie systemu mogą pogarszać reakcję. step: Sprawdź poziom baterii i porównaj działanie na innym porcie.','','',''),
('beginner:ZERO-123','beginner','Peryferia / Peripherals','Klawiatura wpisuje inne znaki','','description: Układ językowy może zostać przypadkowo zmieniony. step: Sprawdź wybrany układ klawiatury w ustawieniach systemu.','','',''),
('beginner:ZERO-124','beginner','Peryferia / Peripherals','Touchpad nie reaguje','','description: Może być wyłączony skrótem klawiaturowym albo w ustawieniach. step: Sprawdź opcję touchpada i działanie zewnętrznej myszy.','','',''),
('beginner:ZERO-125','beginner','Dyski i dane / Storage & Data','Kamera zajęta przez inną aplikację','','description: Jedna aplikacja może blokować dostęp drugiej do kamery. step: Zamknij inne programy korzystające z kamery i sprawdź uprawnienia.','','',''),
('beginner:ZERO-126','beginner','Peryferia / Peripherals','Słuchawki bez dźwięku','','description: Dźwięk może być skierowany na inny port lub urządzenie Bluetooth. step: Wybierz właściwe wyjście audio i sprawdź poziom głośności.','','',''),
('beginner:ZERO-127','beginner','Peryferia / Peripherals','Mikrofon jest zbyt cichy','','description: Problem może dotyczyć wybranego wejścia lub ustawienia poziomu. step: Sprawdź wskaźnik wejścia i ustawienia mikrofonu w aplikacji.','','',''),
('beginner:ZERO-128','beginner','Peryferia / Peripherals','Drukarka jest offline','','description: Status offline może wynikać z połączenia lub kolejki wydruku. step: Sprawdź ekran drukarki i jej połączenie z tą samą siecią.','','',''),
('beginner:ZERO-129','beginner','Serwis i diagnostyka / Service & Diagnostics','Zacięty papier w drukarce','','description: Wyciąganie papieru na siłę może uszkodzić mechanizm. step: Wyłącz urządzenie i postępuj według instrukcji usuwania zacięcia.','','',''),
('beginner:ZERO-130','beginner','Obraz i ekran / Display','Monitor miga','','description: Migotanie może wiązać się z kablem, częstotliwością lub samym ekranem. step: Porównaj inny przewód i zalecane ustawienia monitora.','','',''),
('beginner:ZERO-131','beginner','Obraz i ekran / Display','Martwe i zablokowane piksele','','description: Pojedynczy punkt może być uszkodzony lub stale świecić. step: Sprawdź ekran na jednolitych tłach i warunki gwarancji.','','',''),
('beginner:ZERO-132','beginner','Obraz i ekran / Display','Obraz jest rozciągnięty','','description: Nieprawidłowa rozdzielczość lub skalowanie zmienia proporcje. step: Wybierz natywną rozdzielczość monitora.','','',''),
('beginner:ZERO-133','beginner','Obraz i ekran / Display','Dwa monitory','','description: Brak drugiego obrazu może wynikać z wejścia, kabla lub trybu wyświetlania. step: Sprawdź wykrywanie ekranu i wybrane wejście drugiego monitora.','','',''),
('beginner:ZERO-134','beginner','Obraz i ekran / Display','Projektor i ekran zewnętrzny','','description: Projektor może wymagać wyboru źródła obrazu i obsługiwanego trybu. step: Porównaj wejście projektora oraz ustawienia duplikowania obrazu.','','',''),
('beginner:ZERO-135','beginner','Sieć i internet / Network','Sieć działa tylko na jednym urządzeniu','','description: Taki objaw pomaga odróżnić problem urządzenia od problemu routera. step: Porównaj połączenie dwóch własnych urządzeń w tej samej sieci.','','',''),
('beginner:ZERO-136','beginner','Sieć i internet / Network','Router wymaga ponownego uruchamiania','','description: Częste przerwy mogą dotyczyć routera, zasilania albo dostawcy. step: Zapisz pory awarii i sprawdź kontrolki oraz komunikaty dostawcy.','','',''),
('beginner:ZERO-137','beginner','Sieć i internet / Network','Hasło Wi-Fi a nazwa sieci','','description: Pomylenie podobnych nazw sieci może utrudniać połączenie. step: Sprawdź nazwę własnej sieci na etykiecie lub w ustawieniach routera.','','',''),
('beginner:ZERO-138','beginner','Sieć i internet / Network','Pasmo Wi-Fi 2,4 i 5 GHz','','description: Pasma różnią się zasięgiem i możliwą przepustowością. step: Porównaj działanie własnych urządzeń w obu pasmach, jeśli są dostępne.','','',''),
('beginner:ZERO-139','beginner','Sieć i internet / Network','Ethernet działa, Wi-Fi nie','','description: Różnica wskazuje na problem związany z łącznością bezprzewodową. step: Sprawdź tryb samolotowy i stan karty Wi-Fi.','','',''),
('beginner:ZERO-140','beginner','Sieć i internet / Network','Wi-Fi działa, Ethernet nie','','description: Problem może dotyczyć kabla, portu lub konfiguracji przewodowej. step: Sprawdź drugi sprawny kabel i kontrolki portu.','','','');
